function bindForms(){if($('#backup-reminder'))$('#backup-reminder').onsubmit=e=>{e.preventDefault();const value=Number(Object.fromEntries(new FormData(e.target)).reminderDays);if(!Number.isInteger(value)||value<0||value>365){toast('Choose a valid reminder.');return;}state.backupSettings.reminderDays=value;persist();render();toast('Backup reminder saved.');};if($('#checkin'))$('#checkin').onsubmit=e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target)),day={...d()},limits={energyBefore:[1,10],energyAfter:[1,10],sleep:[0,24],water:[0,500],weight:[1,1000],waist:[1,200],bjjMinutes:[0,500],liftMinutes:[0,500],sleepQuality:[1,5],soreness:[1,5],stress:[1,5]};for(const [k,[min,max]] of Object.entries(limits))if(k in f){const v=f[k]===''?null:Number(f[k]);if(v!==null&&(!Number.isFinite(v)||v<min||v>max||['sleepQuality','soreness','stress'].includes(k)&&!Number.isInteger(v)))throw Error(`Check your ${k} value.`);day[k]=v;}day.notes=f.notes??day.notes;day.recovery=f.recovery??day.recovery;state.days[selected]=day;persist();render();toast('Check-in saved.');}catch(err){toast(err.message);}};if($('#settings')){const form=$('#settings');form.addEventListener('input',()=>{try{const goals=readNutritionForm(form);for(const type of ['bjj','nonBjj'])$('#macro-info-'+type).innerHTML=macroInfoHTML(goals[type]);$('#weekly-nutrition-preview').innerHTML=weeklyNutritionHTML(goals);}catch(err){$('#weekly-nutrition-preview').innerHTML=`<div class="hint" role="status">${esc(err.message)}</div>`;}});form.onsubmit=e=>{e.preventDefault();try{const nutritionGoals=readNutritionForm(e.target),raw=Object.fromEntries(new FormData(e.target));const f=Object.fromEntries(Object.entries(raw).filter(([key])=>!key.startsWith('goal-')));for(const k of ['age','weight','startWeight','goalWeight','energyBaseline','energyGoal','hydrationGoal'])if(k in f&&f[k]!==''){const value=Number(f[k]);if(!Number.isFinite(value)||value<0||value>10000)throw Error('Enter valid profile values.');f[k]=value;}for(const k of ['energyGoal','energyBaseline'])if(k in f&&f[k]!==''&&(f[k]<1||f[k]>10))throw Error('Energy values must be 1–10 or blank.');if('hydrationGoal' in f&&f.hydrationGoal!==''&&(f.hydrationGoal<=0||f.hydrationGoal>500))throw Error('Hydration goal must be between 1 and 500 oz, or blank.');state={...state,profile:{...state.profile,...f},nutritionGoals,nutritionSettingsVersion:NUTRITION_SETTINGS_VERSION};const saved=persist();render();if(saved)toast('Settings and nutrition goals saved.');}catch(err){toast(err.message);}};}if($('#complete'))$('#complete').onchange=e=>{ensure().complete=e.target.checked;if(e.target.checked)snapshotDay(state,selected);persist();render();};if($('#training-type'))$('#training-type').onchange=e=>{ensure().type=e.target.value;persist();render();};if($('#selected-date'))$('#selected-date').onchange=e=>{if(e.target.value){selected=e.target.value;render();}};if($('#backup-file'))$('#backup-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('Backup is too large (maximum 5MB).');const restored=validateBackup(JSON.parse(await file.text()));restorePreview(restored);}catch(err){toast(err.message);}};}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied. Paste into ChatGPT.');}catch{if($('#modal').open&&$('#photo-prompt-output')){$('#photo-prompt-output').focus();$('#photo-prompt-output').select();toast('Select and copy the prompt manually.');return;}openModal(`<h2>Copy your prompt</h2><p>Select all and copy the text below.</p><textarea id="copy-fallback" class="prompt-box" style="width:100%" readonly>${esc(text)}</textarea><div class="modal-actions"><button class="btn" data-close>Done</button></div>`);$('#copy-fallback').focus();$('#copy-fallback').select();}}
