if(action==='commit-import'&&draft){const imported=draft;const dates=Object.keys(imported).sort();confirmDialog('Import this reviewed week?',`Replace planned meals for ${pretty(dates[0])} through ${pretty(dates.at(-1))}? Your eaten food and check-ins stay separate.`,()=>{for(const k of dates)state.plans[k]={...imported[k],meals:imported[k].meals.map(m=>({...m,id:crypto.randomUUID()}))};persist();draft=null;planDay=dates[0];planStart=dates[0];view='plan';render();toast('Meal plan imported.');});}
